const webhookBody = $('Test Webhook').first().json.body || {};
const rawQuery = (webhookBody.query || webhookBody.prompt || webhookBody.message || '').trim();
const rawDest = (webhookBody.destination || '').trim();
const rawText = `${rawDest} ${rawQuery}`.trim();
const sessionId = (webhookBody.sessionId || '').trim();

function detectLanguage(text) {
  if (!text) return null;
  if (/[\u4e00-\u9fa5]/.test(text)) return 'zh';
  if (/[\uac00-\ud7a3]/.test(text)) return 'ko';
  if (/[\u3040-\u30ff]/.test(text)) return 'ja';

  const viDiacritics = /[àáạảãâầấậẩẫăằắặẳẵèéẹẻẽêềếệểễìíịỉĩòóọỏõôồốộổỗơờớợởỡùúụủũưừứựửữỳýỵỷỹđ]/i;
  if (viDiacritics.test(text)) return 'vi';

  const enWords = /\b(the|a|an|is|are|was|were|in|at|which|on|travel|tour|tours|guide|guides|trek|trekking|hotel|stay|looking|want|recommend|suggest|what|where|how|who|can|could|price|cost|day|night|trip|hello|hi|please|localmate|vietnam|thank|thanks|contact|book|booking|available|experience|information|info)\b/i;
  if (enWords.test(text)) return 'en';

  const viWords = /\b(cho|toi|minh|ban|nao|o|day|gi|the|nhe|nha|a|voi|diem|lich|trinh|huong|dan|vien)\b/i;
  if (viWords.test(text)) return 'vi';

  return null;
}

const detectedLang = detectLanguage(rawText);
const lang = detectedLang || 'vi';

function removeVietnameseTones(str) {
  return (str || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd').replace(/Đ/g, 'D')
    .toLowerCase();
}

const DESTINATION_DICTIONARY = [
  {
    canonical: 'Mù Cang Chải',
    aliases: [
      'mu cang chai', 'mù cang chải', 'mù căng chải', 'mucangchai', 'mu kang chai',
      'mu cang chay', 'mucang chay', 'la pan tan', 'la pán tẩn', 'khau pha', 'đèo khau phạ',
      'ruộng bậc thang', 'ruong bac thang', 'mâm xôi', 'đồi mâm xôi', 'móng ngựa', 'lúa chín', 'mùa vàng',
      'mù chang chải', '木江界'
    ]
  },
  {
    canonical: 'Hồ Thác Bà',
    aliases: [
      'hồ thác bà', 'ho thac ba', 'thac ba', 'thác bà', 'thac ba lake',
      'động thủy tiên', 'dong thuy tien', 'an bình village', 'an binh village',
      'thủy điện thác bà', 'chèo sup', 'đảo hoa', 'đảo thiên đường'
    ]
  },
  {
    canonical: 'Trạm Tấu',
    aliases: [
      'trạm tấu', 'tram tau', 'khoáng nóng', 'khoang nong', 'hot springs', 'hot spring',
      'tà chì nhù', 'ta chi nhu', 'tà xùa', 'ta xua', 'bản hốc', 'tắm khoáng'
    ]
  },
  {
    canonical: 'Suối Giàng',
    aliases: [
      'suối giàng', 'suoi giang', 'chè shan tuyết', 'che shan tuyet', 'shan tuyet',
      'lau camping', 'phình hồ', 'chè cổ thụ'
    ]
  },
  {
    canonical: 'Nghĩa Lộ',
    aliases: ['nghĩa lộ', 'nghia lo', 'mường lò', 'muong lo', 'sà rèn', 'xòe thái']
  },
  {
    canonical: 'Yên Bái',
    aliases: ['yên bái', 'yen bai']
  }
];

function resolveDestination(text) {
  if (!text) return null;
  const lower = text.toLowerCase();
  const lowerNoTone = removeVietnameseTones(text);

  for (const item of DESTINATION_DICTIONARY) {
    if (lower.includes(item.canonical.toLowerCase())) {
      return item.canonical;
    }
    for (const alias of item.aliases) {
      if (lower.includes(alias)) {
        return item.canonical;
      }
      const aliasNoTone = removeVietnameseTones(alias);
      if (lowerNoTone.includes(aliasNoTone)) {
        return item.canonical;
      }
    }
  }
  return null;
}

// Extract specific attraction keyword for search in tour titles/content
function extractAttractionKeyword(text) {
  if (!text) return '';
  const lower = text.toLowerCase();
  const keywords = [
    'khoáng nóng', 'khoang nong', 'hot spring', 'tắm khoáng',
    'săn mây', 'san may', 'tà chì nhù', 'ta chi nhu', 'tà xùa',
    'ruộng bậc thang', 'mâm xôi', 'móng ngựa', 'lúa chín', 'mùa vàng',
    'chèo sup', 'thủy điện', 'động thủy tiên', 'đảo hoa', 'đảo thiên đường',
    'chè shan tuyết', 'che shan tuyet', 'shan tuyet', 'lau camping',
    'bản hốc', 'sà rèn', 'xòe thái', 'an bình village', 'tú lệ'
  ];
  for (const kw of keywords) {
    if (lower.includes(kw)) return kw;
  }
  return '';
}

const explicitDest = resolveDestination(rawDest) || resolveDestination(rawQuery);
const canonicalDestination = explicitDest || null;

const lowerQuery = rawQuery.toLowerCase();
const lowerNoTone = removeVietnameseTones(rawQuery);

// General greetings: short message containing only greeting
const isGreeting = (/(^(xin\s*)?chào|hello|hi|alo|bạn ơi|hey)\b/i.test(lowerQuery) || /^(chao|xin chao)\b/i.test(lowerNoTone)) && lowerQuery.length < 20 && !/(muốn|đi chơi|gợi ý|tour|du lịch|đâu|lịch trình)/i.test(lowerQuery);
const isThanksGoodbye = (/(cảm ơn|cam on|thanks|thank you|tạm biệt|bye|goodbye)/i.test(lowerQuery) || /(cam on|tam biet)/i.test(lowerNoTone)) && lowerQuery.length < 35;

function isGibberish(text) {
  if (!text || text.length === 0) return false;
  const clean = text.toLowerCase().replace(/[^a-z0-9à-ỹ]/gi, '');
  if (clean.length === 0) return true;
  if (/(.)\1{4,}/.test(clean)) return true;
  const keyboardPatterns = /(asdfgh|qwerty|zxcvbn|dfghjk|qazwsx|123456)/i;
  if (keyboardPatterns.test(clean) && clean.length <= 15) return true;
  if (/[bcdfghjklmnpqrstvwxyz]{6,}/i.test(clean)) return true;
  if (/^\d{5,}$/.test(clean)) return true;
  return false;
}

function isOutOfScope(text) {
  const offTopicKeywords = [
    'phương trình', 'toán học', 'giải toán', 'lập trình', 'javascript', 'python', 'sửa xe',
    'bán nhà', 'bất động sản', 'chứng khoán', 'bitcoin', 'crypto', 'tài chính',
    'thời sự', 'chính trị', 'tin tức thế giới', 'math', 'equation'
  ];
  return offTopicKeywords.some(kw => text.toLowerCase().includes(kw));
}

let intent = 'TRAVEL_QUERY';
let skipApi = false;
let directReply = null;

if (isGreeting) {
  intent = 'GREETING';
  skipApi = true;
  directReply = lang === 'en'
    ? "Hello! I'm **LocalMate AI** - your personal Vietnam local travel assistant from VietSage. 🌿\n\nHow can I help you today? Are you planning a trip to Northwest Vietnam (Mu Cang Chai, Tram Tau, Thac Ba Lake...)?"
    : "Dạ xin chào bạn! Mình là **LocalMate AI** - trợ lý du lịch bản địa của VietSage rất vui được trò chuyện cùng bạn. 🌿\n\nHôm nay bạn đang quan tâm đến điểm đến hoặc trải nghiệm nào ở Tây Bắc (Mù Cang Chải, Trạm Tấu khoáng nóng, Hồ Thác Bà, Suối Giàng...) để mình hỗ trợ nhé?";
} else if (isThanksGoodbye) {
  intent = 'THANKS_GOODBYE';
  skipApi = true;
  const destTag = canonicalDestination ? ` khám phá **${canonicalDestination}**` : '';
  directReply = lang === 'en'
    ? `You're very welcome! Feel free to ask anytime you need travel tips or local guides${canonicalDestination ? ` in **${canonicalDestination}**` : ' in Vietnam'}. Have a wonderful journey! ✨`
    : `Dạ không có gì ạ! Rất vui được đồng hành cùng bạn${destTag}. Bất cứ khi nào bạn cần thêm thông tin lịch trình hay muốn kết nối LocalMate bản địa, cứ nhắn mình nhé. Chúc bạn có chuyến đi thật trọn vẹn và ý nghĩa! ✨`;
} else if (isGibberish(rawText)) {
  intent = 'GIBBERISH';
  skipApi = true;
  directReply = lang === 'en'
    ? "Hello! I might not have caught your message clearly. I'm **LocalMate AI**, an assistant for local travel in Vietnam. Could you please specify which destination or activity you're interested in?"
    : "Dạ LocalMate AI chưa hiểu rõ tin nhắn của bạn. Mình là trợ lý du lịch bản địa của VietSage. Bạn có thể cho mình biết bạn đang quan tâm đến điểm đến hay lịch trình nào không nhé!";
} else if (isOutOfScope(rawText)) {
  intent = 'OUT_OF_SCOPE';
  skipApi = true;
  directReply = "Dạ mình là LocalMate AI chuyên về tư vấn du lịch và văn hóa bản địa Việt Nam. Câu hỏi này nằm ngoài lĩnh vực của mình rồi ạ. Nếu bạn cần gợi ý về các điểm du lịch Tây Bắc hay tìm hướng dẫn viên bản địa, cứ nhắn mình nha!";
}

const limit = Math.min(Math.max(Number(webhookBody.limit || 5), 1), 10);

// Key: If user didn't mention a specific attraction keyword, pass empty query so API returns all top tours
const attractionKeyword = extractAttractionKeyword(rawQuery);
const apiDestination = canonicalDestination || '';
const apiQuery = attractionKeyword || '';

return [{
  json: {
    intent,
    skipApi,
    lang,
    sessionId,
    canonicalDestination,
    cleanQuery: rawQuery,
    destination: apiDestination,
    query: apiQuery,
    limit,
    directReply
  }
}];

const norm = $('Input Normalizer & Intent Classifier').first().json || {};
const lang = norm.lang || 'vi';

let suggestions = [];
if (lang === 'en') {
  suggestions = [
    { id: 'fb_1', label: '🌾 Mu Cang Chai Tours', query: 'Recommend the best tours in Mu Cang Chai' },
    { id: 'fb_2', label: '♨️ Tram Tau Hot Springs', query: 'What are the top hot springs in Tram Tau?' },
    { id: 'fb_3', label: '🧭 Local Guides', query: 'Are there verified local guides available?' }
  ];
} else {
  suggestions = [
    { id: 'fb_1', label: '🌾 Tour Mù Cang Chải', query: 'Gợi ý tour ruộng bậc thang Mù Cang Chải đẹp nhất' },
    { id: 'fb_2', label: '♨️ Khoáng nóng Trạm Tấu', query: 'Trạm Tấu có suối khoáng nóng và điểm săn mây nào nổi bật?' },
    { id: 'fb_3', label: '🧭 Hướng dẫn viên bản địa', query: 'Tôi muốn tìm hiểu hướng dẫn viên bản địa ở Tây Bắc' }
  ];
}

return [{ json: {
  status: 200,
  reply: norm.directReply || 'Dạ LocalMate AI xin chào bạn! Bạn đang quan tâm đến điểm đến hay dịch vụ nào ở Tây Bắc ạ?',
  suggestions,
  knowledgeVersion: 'none',
  cached: false
} }];

const envelope = $input.first().json || {};
const payload = envelope.data?.data || envelope.data || envelope;
const norm = $('Input Normalizer & Intent Classifier').first().json || {};
const webhookBody = $('Test Webhook').first().json.body || {};
const rawDest = (webhookBody.destination || '').trim();

const tours = Array.isArray(payload.tours) ? payload.tours : [];
const guides = Array.isArray(payload.guides) ? payload.guides : [];
const language = norm.lang || 'vi';
const destination = norm.canonicalDestination || norm.destination || '';
const question = norm.cleanQuery || norm.query || '';
const hotelContext = rawDest || 'Khách sạn tại Tây Bắc';

const compactKnowledge = {
  hotel: hotelContext,
  destination: destination || 'Toàn vùng Tây Bắc (Yên Bái)',
  tours: tours.slice(0, 5).map(({ tourCode, title, destination: d, duration, highlights, content }) => ({
    tourCode, title, destination: d, duration, highlights,
    content: typeof content === 'string' ? content.slice(0, 1500) : ''
  })),
  guides: guides.slice(0, 4).map(({ guideCode, fullName, operatingRegions, languages, specialties, rating, dailyRateVnd, bio }) => ({
    guideCode, fullName, operatingRegions, languages, specialties, rating, dailyRateVnd, bio
  }))
};

const userPrompt = [
  'LANGUAGE: ' + language,
  'HOTEL_GUEST_IS_STAYING_AT: ' + hotelContext,
  'GUEST_QUESTION: ' + question,
  'DESTINATION: ' + (destination || 'Toàn vùng Tây Bắc (Yên Bái)'),
  'KNOWLEDGE_OF_AVAILABLE_TOURS_AND_GUIDES:',
  JSON.stringify(compactKnowledge)
].join('\n');

return [{ json: {
  knowledgeVersion: payload.knowledgeVersion || 'unknown',
  language,
  question,
  destination,
  hotelContext,
  knowledge: compactKnowledge,
  userPrompt
} }];

const model = $input.first().json || {};
const prepared = $('Prepare LocalMate AI Prompt').first().json || {};
const messages = Array.isArray(model.output) ? model.output : [];
const rawReply = messages.flatMap(m => Array.isArray(m.content) ? m.content : []).find(c => c?.type === 'output_text')?.text || '';

if (typeof rawReply !== 'string' || !rawReply.trim()) throw new Error('AI model returned no text');

let cleanReply = rawReply.trim();
const suggestions = [];

// Extract suggestions if model followed the format
const marker = 'GỢI Ý TIẾP THEO:';
const markerIdx = cleanReply.indexOf(marker);
if (markerIdx !== -1) {
  const suggestionsBlock = cleanReply.slice(markerIdx + marker.length).trim();
  cleanReply = cleanReply.slice(0, markerIdx).trim();

  const lines = suggestionsBlock.split('\n');
  for (const line of lines) {
    const trimmed = line.replace(/^[\s\-*•\d.]+\s*/, '').trim();
    if (trimmed.length > 2 && trimmed.length < 50) {
      suggestions.push({
        id: 'sugg_' + suggestions.length,
        label: trimmed.slice(0, 25),
        query: trimmed
      });
      if (suggestions.length >= 3) break;
    }
  }
}

// Fallback suggestions based on context if not extracted
if (suggestions.length === 0) {
  const dest = prepared.destination || '';
  if (dest.includes('Trạm Tấu')) {
    suggestions.push(
      { id: 'tt_1', label: '♨️ Suối khoáng nóng', query: 'Suối khoáng nóng Trạm Tấu giá vé và dịch vụ thế nào?' },
      { id: 'tt_2', label: '⛅ Săn mây Tà Chì Nhù', query: 'Lịch trình săn mây đỉnh Tà Chì Nhù Trạm Tấu' },
      { id: 'tt_3', label: '🧭 Hướng dẫn viên', query: 'Có hướng dẫn viên bản địa dẫn tour Trạm Tấu không?' }
    );
  } else if (dest.includes('Mù Cang Chải')) {
    suggestions.push(
      { id: 'mcc_1', label: '🌾 Tour Mù Cang Chải', query: 'Gợi ý tour ruộng bậc thang Mù Cang Chải đẹp nhất' },
      { id: 'mcc_2', label: '📸 Điểm chụp ảnh đẹp', query: 'Đồi Mâm Xôi và Móng Ngựa nên đi vào giờ nào?' },
      { id: 'mcc_3', label: '🧭 LocalMate bản địa', query: 'Kết nối hướng dẫn viên bản địa tại Mù Cang Chải' }
    );
  } else {
    suggestions.push(
      { id: 'gen_1', label: '🌾 Tour Mù Cang Chải', query: 'Tư vấn tour ruộng bậc thang Mù Cang Chải' },
      { id: 'gen_2', label: '♨️ Khoáng nóng Trạm Tấu', query: 'Gợi ý trải nghiệm tắm khoáng nóng Trạm Tấu' },
      { id: 'gen_3', label: '⛵ Du ngoạn Hồ Thác Bà', query: 'Có tour nào khám phá Hồ Thác Bà không?' }
    );
  }
}

return [{ json: {
  status: 200,
  reply: cleanReply,
  suggestions,
  knowledgeVersion: prepared.knowledgeVersion || 'unknown',
  cached: false
} }];
